using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.Profiling;using Newtonsoft.Json;
namespace IslandGame {
 public sealed class MountDeviceProbe:MonoBehaviour {
  readonly List<float> frames=new List<float>(),transitions=new List<float>();readonly List<object> samples=new List<object>();readonly Dictionary<int,List<float>> perZone=new Dictionary<int,List<float>>();
  public readonly Dictionary<string,int> AttackMotionContacts=new Dictionary<string,int>();public int ConfirmedAttackContacts,WrongAttackPose;public float MaxContactDelay;int seenContacts;
  RpgSession session;NativeBattle battle;Battle3DView view;float began,nextReport;int previousZone=-1;public int GroundMisses,GroundSamples,Errors;public float MaxGroundGap;public int ScenePeak,GraphPeak;string output;bool ready,finished;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void StartOnAndroid(){
   if(!Debug.isDebugBuild||Application.isEditor)return;
   #if UNITY_ANDROID
   try{using(var player=new AndroidJavaClass("com.unity3d.player.UnityPlayer"))using(var activity=player.GetStatic<AndroidJavaObject>("currentActivity"))using(var intent=activity.Call<AndroidJavaObject>("getIntent")){if(intent.Call<string>("getStringExtra","mount_probe")!="1")return;var go=new GameObject("Mount Android validation");DontDestroyOnLoad(go);var probe=go.AddComponent<MountDeviceProbe>();probe.StartCoroutine(probe.Boot(intent.Call<string>("getStringExtra","mount_server")??"http://127.0.0.1:18108"));}}
   catch(Exception e){Debug.LogError("Mount validation startup: "+e.Message);}
   #endif
  }
  IEnumerator Boot(string origin){IslandApp app;do{app=FindFirstObjectByType<IslandApp>();yield return null;}while(!app);app.StartMountTest(origin);Begin();}
  public void Begin(){session=FindFirstObjectByType<RpgSession>();battle=FindFirstObjectByType<NativeBattle>();view=FindFirstObjectByType<Battle3DView>();began=Time.realtimeSinceStartup;output=Path.Combine(Application.persistentDataPath,"mount-report.json");Application.logMessageReceived+=Log;ready=true;}
  void Log(string condition,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)Errors++;}
  void Update(){if(!ready||finished||!session||session.State==null)return;if((string)session.State["status"]=="won"){finished=true;Save();return;}if(!view)view=FindFirstObjectByType<Battle3DView>();if(view&&view.ContactFeedback!=null&&view.ContactFeedback.ConsumedContacts>0&&seenContacts!=view.ContactFeedback.ConsumedContacts){seenContacts=view.ContactFeedback.ConsumedContacts;var f=view.ContactFeedback;foreach(var fx in battle.PresentationState?["fx"] as Newtonsoft.Json.Linq.JArray??new Newtonsoft.Json.Linq.JArray())if((int?)fx["attackId"]==f.LastAttackId&&(string)fx["damageKind"]=="attack"&&((string)fx["target"]??"").StartsWith("mob")){ConfirmedAttackContacts++;string motion=(string)fx["definitionId"]??"unknown";AttackMotionContacts[motion]=AttackMotionContacts.TryGetValue(motion,out var count)?count+1:1;MaxContactDelay=Mathf.Max(MaxContactDelay,battle.VisualTime-f.LastContactAt);if(view.HeroAttackId!=f.LastAttackId||view.HeroAttackProgress<.31f||!view.HeroAttackActive&&view.HeroAttackProgress>.63f)WrongAttackPose++;break;}}float age=Time.realtimeSinceStartup-began;int zone=(int?)session.State["room"]??-1;var stream=MountZoneStream.Current;bool bossStage=(string)session.State["routeStage"]=="boss";bool transition=bossStage?(string)session.State["phase"]=="boss-loading":!stream||!stream.IsReady;if(stream)ScenePeak=Mathf.Max(ScenePeak,stream.LoadedCount);GraphPeak=Mathf.Max(GraphPeak,RuntimeAnimationPlayer.ActiveGraphs);
   if(age>15){float ms=Time.unscaledDeltaTime*1000;if(transition)transitions.Add(ms);else {frames.Add(ms);if(!perZone.TryGetValue(zone,out var list))perZone[zone]=list=new List<float>();list.Add(ms);}}
   if(view&&view.HeroTarget&&!transition&&battle.HeroAirHeight<1){var p=view.HeroTarget.position;if(Physics.Raycast(p+Vector3.up*2,Vector3.down,out var h,6,1<<30)){GroundSamples++;MaxGroundGap=Mathf.Max(MaxGroundGap,Mathf.Abs(p.y-h.point.y));}else GroundMisses++;}
   if(Time.realtimeSinceStartup>=nextReport||zone!=previousZone){previousZone=zone;nextReport=Time.realtimeSinceStartup+10;samples.Add(new{age,zone,kills=(int?)session.State["kills"],spawned=(int?)session.State["spawned"],active=view?view.ActorCount:0,loaded=stream?stream.LoadedCount:0,managed=GC.GetTotalMemory(false),allocated=Profiler.GetTotalAllocatedMemoryLong(),reserved=Profiler.GetTotalReservedMemoryLong(),rtt=session.LastRttMilliseconds,localCombat=session.UsesLocalTraining,networkRequests=session.NetworkRequestCount,localSteps=session.LocalSteps,localMaxBatchMs=session.LocalMaxBatchMilliseconds,droppedSeconds=session.LocalDroppedSeconds,phase=(string)session.State["phase"]});Save();}
  }
  static object Stats(List<float> values){if(values.Count==0)return new{samples=0};var a=values.OrderBy(x=>x).ToArray();float mean=a.Average();return new{samples=a.Length,meanMs=mean,averageFps=1000/mean,p50=a[(int)((a.Length-1)*.50)],p95=a[(int)((a.Length-1)*.95)],p99=a[(int)((a.Length-1)*.99)],max=a[a.Length-1],over50ms=a.Count(x=>x>50),over100ms=a.Count(x=>x>100)};}
  public void Save(){if(string.IsNullOrEmpty(output))return;var report=new{platform=Application.platform.ToString(),device=SystemInfo.deviceModel,gpu=SystemInfo.graphicsDeviceName,resolution=Screen.width+"x"+Screen.height,unity=Application.unityVersion,version=Application.version,localCombat=session&&session.UsesLocalTraining,networkRequests=session?session.NetworkRequestCount:0,localSteps=session?session.LocalSteps:0,localMaxBatchMs=session?session.LocalMaxBatchMilliseconds:0,droppedSeconds=session?session.LocalDroppedSeconds:0,age=Time.realtimeSinceStartup-began,status=(string)session?.State?["status"],routeStage=(string)session?.State?["routeStage"],camera=battle?battle.CameraRig.Mode.ToString():null,ConfirmedAttackContacts,AttackMotionContacts,WrongAttackPose,MaxContactDelay,room=(int?)session?.State?["room"],kills=(int?)session?.State?["kills"],steady=Stats(frames),transition=Stats(transitions),zones=perZone.ToDictionary(p=>p.Key,p=>Stats(p.Value)),ScenePeak,GraphPeak,GroundSamples,GroundMisses,MaxGroundGap,Errors,samples};File.WriteAllText(output,JsonConvert.SerializeObject(report,Formatting.Indented));}
  void OnApplicationPause(bool paused){if(paused)Save();}void OnDestroy(){Application.logMessageReceived-=Log;if(ready)Save();}
 }
}
